	// Permission inspection.
	mux.HandleFunc("/rest/api/1.0/admin/permissions/users", func(w http.ResponseWriter, r *http.Request) {
		write(w, `{"values":[{"user":{"name":"hkjang"},"permission":"LICENSED_USER"}]}`)
